def _find_best_span_in_raw(raw_text, cleaned, fixed_span):
    """Find the best matching span from the raw text for a cleaned/fixed segment."""
    # The fixed_span has typo corrections applied. We need to find
    # the original (uncorrected) text in raw_text.

    # Reverse typo map: correct → original typo
    reverse_typo = {v: k for k, v in TYPO_MAP.items()}

    # Try progressively applying all reverse typo corrections
    for candidate_base in [fixed_span, cleaned]:
        # Try each single replacement
        for correct, original in reverse_typo.items():
            if correct in candidate_base:
                rev = candidate_base.replace(correct, original)
                if rev in raw_text:
                    return rev

        # Try all replacements at once
        rev = candidate_base
        for correct, original in reverse_typo.items():
            rev = rev.replace(correct, original)
        if rev in raw_text:
            return rev

        # Try all combinations of 2 replacements
        items = [(c, o) for c, o in reverse_typo.items() if c in candidate_base]
        for i, (c1, o1) in enumerate(items):
            for c2, o2 in items[i+1:]:
                rev = candidate_base.replace(c1, o1).replace(c2, o2)
                if rev in raw_text:
                    return rev

    # Direct match check
    if fixed_span in raw_text:
        return fixed_span
    if cleaned in raw_text:
        return cleaned

    # Last resort: find the longest substring of fixed_span that exists in raw_text
    # Try trimming from both ends
    for length in range(len(fixed_span), 4, -1):
        for start in range(len(fixed_span) - length + 1):
            sub = fixed_span[start:start + length]
            if sub in raw_text and len(sub) > 5:
                return sub

    return fixed_span

