import json, csv

with open('output/solution.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Load codebooks for validation
codebooks = {}
for pid in ['P1_POWER', 'P2_CTRL', 'P3_RF']:
    with open(f'data/codebook_{pid}.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        codes = {}
        for row in reader:
            codes[row['code']] = row['standard_label']
        codebooks[pid] = codes

# Comprehensive validation
errors = []
records = data['records']

print(f'Total records: {len(records)}')
print()

# 1. Check all records have required fields
for r in records:
    for field in ['record_id', 'product_id', 'station', 'engineer_id', 'raw_reason_text', 'normalized']:
        if field not in r:
            errors.append(f'{r.get(\"record_id\",\"?\")} missing field {field}')

    for n in r['normalized']:
        for field in ['segment_id', 'span_text', 'pred_code', 'pred_label', 'confidence', 'rationale']:
            if field not in n:
                errors.append(f'{r[\"record_id\"]} segment missing field {field}')

# 2. Check segment_id format
for r in records:
    for i, n in enumerate(r['normalized']):
        expected = f\"{r['record_id']}-S{i+1}\"
        if n['segment_id'] != expected:
            errors.append(f\"{r['record_id']}: segment_id {n['segment_id']} != expected {expected}\")

# 3. Check pred_code and pred_label match codebook or are UNKNOWN
for r in records:
    pid = r['product_id']
    cb = codebooks.get(pid, {})
    for n in r['normalized']:
        code = n['pred_code']
        label = n['pred_label']
        if code == 'UNKNOWN':
            if label != '':
                errors.append(f\"{r['record_id']}: UNKNOWN code should have empty label, got '{label}'\")
        else:
            if code not in cb:
                errors.append(f\"{r['record_id']}: pred_code {code} not in {pid} codebook\")
            elif cb[code] != label:
                errors.append(f\"{r['record_id']}: pred_label mismatch for {code}: '{label}' vs '{cb[code]}'\")

# 4. Check confidence range
for r in records:
    for n in r['normalized']:
        conf = n['confidence']
        if not (0.0 <= conf <= 1.0):
            errors.append(f\"{r['record_id']}: confidence {conf} out of range\")
        if n['pred_code'] == 'UNKNOWN' and conf >= 0.5:
            errors.append(f\"{r['record_id']}: UNKNOWN confidence {conf} >= 0.5 (should be < 0.5)\")
        if n['pred_code'] != 'UNKNOWN' and conf < 0.5:
            errors.append(f\"{r['record_id']}: non-UNKNOWN confidence {conf} < 0.5\")

# 5. Check span_text in raw_reason_text
for r in records:
    raw = r['raw_reason_text']
    for n in r['normalized']:
        if n['span_text'] not in raw:
            errors.append(f\"{r['record_id']}: span_text not in raw_reason_text\")

# 6. Verify every record from CSV is present
with open('data/test_center_logs.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    csv_ids = set(row['record_id'] for row in reader)

json_ids = set(r['record_id'] for r in records)
missing = csv_ids - json_ids
extra = json_ids - csv_ids
if missing:
    errors.append(f'Missing {len(missing)} records from CSV: {list(missing)[:5]}')
if extra:
    errors.append(f'Extra {len(extra)} records not in CSV: {list(extra)[:5]}')

if errors:
    print(f'ERRORS FOUND: {len(errors)}')
    for e in errors[:20]:
        print(f'  - {e}')
else:
    print('ALL VALIDATIONS PASSED!')

print()
# Confidence statistics
import statistics
all_confs = [n['confidence'] for r in records for n in r['normalized']]
known_confs = [n['confidence'] for r in records for n in r['normalized'] if n['pred_code'] != 'UNKNOWN']
unk_confs = [n['confidence'] for r in records for n in r['normalized'] if n['pred_code'] == 'UNKNOWN']

print(f'=== Confidence Distribution ===')
print(f'All segments:')
print(f'  Count: {len(all_confs)}')
print(f'  Mean: {statistics.mean(all_confs):.4f}')
print(f'  Stdev: {statistics.stdev(all_confs):.4f}')
print(f'  Min/Max: {min(all_confs):.2f} / {max(all_confs):.2f}')
q = statistics.quantiles(all_confs, n=10)
print(f'  Deciles: {[round(x,2) for x in q]}')

print(f'Non-UNKNOWN:')
print(f'  Count: {len(known_confs)}')
print(f'  Mean: {statistics.mean(known_confs):.4f}')
q = statistics.quantiles(known_confs, n=10)
print(f'  Deciles: {[round(x,2) for x in q]}')

print(f'UNKNOWN:')
print(f'  Count: {len(unk_confs)}')
print(f'  Mean: {statistics.mean(unk_confs):.4f}')
print(f'  Min/Max: {min(unk_confs):.2f} / {max(unk_confs):.2f}')

# Unique confidence values
unique_confs = sorted(set(all_confs))
print(f'  Unique confidence values ({len(unique_confs)}): {unique_confs}')
